-- README lua example snippets check. Generated by @voxgig/sdkgen.
--
-- COMPLETENESS GATE over every ```lua block in all three docs that ship
-- lua examples: the root README.md, the lua/README.md, and the
-- lua/REFERENCE.md. For every block:
--   1. Syntax: each block must compile with Lua's load().
--   2. Offline run: every runnable block (one that builds a client or
--      references `client`) is EXECUTED with the mock transport (no
--      network). Each client constructor is rewritten to the seeded
--      test-mode form, and fragments that only use `client` get a seeded
--      test client injected. A call to a method that does not exist raises
--      "call a nil value" and FAILS the test. A seeded-fixture miss surfaces
--      as a tolerated (nil, err) not-found domain error, not a raised error.
--   3. Completeness: total == executed + illustration per doc. A block that
--      is neither runnable nor an explicit comment-only placeholder FAILS
--      the gate, so no runnable example can be silently skipped.

local SDK_MODULE = "seqbench-mcp_sdk"

-- A test-mode client seeded with a fixture for every entity. The constructor
-- of each runnable snippet is rewritten to this form so the offline mock has
-- data to return.
local TEST_SEED = '{ entity = { ["alphafold_lookup"] = { ["test01"] = { id = "test01" } }, ["aso_design"] = { ["test01"] = { id = "test01" } }, ["base_editing_design"] = { ["test01"] = { id = "test01" } }, ["batch"] = { ["test01"] = { id = "test01" } }, ["batch__workflow"] = { ["test01"] = { id = "test01" } }, ["characterize_sequence"] = { ["test01"] = { id = "test01" } }, ["cloning_simulate"] = { ["test01"] = { id = "test01" } }, ["codon_adaptation_index"] = { ["test01"] = { id = "test01" } }, ["codon_optimize"] = { ["test01"] = { id = "test01" } }, ["construct_autofix"] = { ["test01"] = { id = "test01" } }, ["construct_qc"] = { ["test01"] = { id = "test01" } }, ["crispr_grna_design"] = { ["test01"] = { id = "test01" } }, ["crispr_hdr_donor"] = { ["test01"] = { id = "test01" } }, ["crispr_offtarget_check"] = { ["test01"] = { id = "test01" } }, ["cross_dimer"] = { ["test01"] = { id = "test01" } }, ["dna_molarity"] = { ["test01"] = { id = "test01" } }, ["double_digest"] = { ["test01"] = { id = "test01" } }, ["export_echo_picklist"] = { ["test01"] = { id = "test01" } }, ["export_opentrons_protocol"] = { ["test01"] = { id = "test01" } }, ["export_plate_layout"] = { ["test01"] = { id = "test01" } }, ["expression_heatmap_cluster"] = { ["test01"] = { id = "test01" } }, ["fastq_qc_report"] = { ["test01"] = { id = "test01" } }, ["fastq_trim"] = { ["test01"] = { id = "test01" } }, ["find_orf"] = { ["test01"] = { id = "test01" } }, ["format_sequence"] = { ["test01"] = { id = "test01" } }, ["functional_enrichment"] = { ["test01"] = { id = "test01" } }, ["gc_content"] = { ["test01"] = { id = "test01" } }, ["gene_dossier"] = { ["test01"] = { id = "test01" } }, ["gene_expression"] = { ["test01"] = { id = "test01" } }, ["gene_model"] = { ["test01"] = { id = "test01" } }, ["golden_gate_fidelity"] = { ["test01"] = { id = "test01" } }, ["hgvs_convert"] = { ["test01"] = { id = "test01" } }, ["id_map_poll"] = { ["test01"] = { id = "test01" } }, ["id_map_submit"] = { ["test01"] = { id =